using System.Globalization;
using System.Text;

namespace Vericairn.Records.Text;

/// <summary>
/// Unicode normalization (NFC, NFD, NFKC and NFKD), full case folding and general categories in managed code, from the Unicode
/// Character Database tables pinned in this assembly (<see cref="UnicodeVersion"/>, generated by
/// <c>tools/generate-unicode-folding.py</c>). Nothing here reads the platform's ICU, the current culture or the process's
/// globalization mode, so every result is identical on every platform and in the product's invariant-globalization build, where
/// <see cref="string.Normalize()"/> does nothing. Ill-formed UTF-16 is kept: a lone surrogate passes through unchanged, as a
/// starter with no mapping.
/// </summary>
internal static partial class UnicodeFolding
{
    private const int SBase = 0xAC00, LBase = 0x1100, VBase = 0x1161, TBase = 0x11A7;
    private const int LCount = 19, VCount = 21, TCount = 28, NCount = VCount * TCount, SCount = LCount * NCount;

    // Below U+0300 every code point is a starter and none is the second of a composite pair; the generator checks both.
    private const int FirstCombining = 0x300;

    /// <summary>Canonical decomposition followed by canonical composition (NFC).</summary>
    internal static string Nfc(string text) => Normalize(text, compatibility: false, compose: true);

    /// <summary>Canonical decomposition (NFD).</summary>
    internal static string Nfd(string text) => Normalize(text, compatibility: false, compose: false);

    /// <summary>Compatibility decomposition followed by canonical composition (NFKC).</summary>
    internal static string Nfkc(string text) => Normalize(text, compatibility: true, compose: true);

    /// <summary>Compatibility decomposition (NFKD).</summary>
    internal static string Nfkd(string text) => Normalize(text, compatibility: true, compose: false);

    /// <summary>Full case folding: the mappings of status C and F in CaseFolding.txt (so <c>ß</c> folds to <c>ss</c>), without the Turkic ones.</summary>
    internal static string CaseFold(string text)
    {
        ArgumentNullException.ThrowIfNull(text);
        if (IsAscii(text)) return AsciiLower(text);
        var builder = new StringBuilder(text.Length);
        for (int i = 0; i < text.Length;)
        {
            int cp = Next(text, ref i);
            if (Find(FoldingKeys, cp) is int index and >= 0)
            {
                for (int v = FoldingOffsets[index]; v < FoldingOffsets[index + 1]; v++) Append(builder, FoldingValues[v]);
            }
            else Append(builder, cp);
        }

        return builder.ToString();
    }

    /// <summary>
    /// NFKC, then full case folding, then NFKC again, which recomposes what folding decomposed: the text form compared caselessly and
    /// across compatibility variants (<c>ﬁ</c>, full-width forms, superscripts). Unlike the NFKC_Casefold property, default
    /// ignorable code points are kept.
    /// </summary>
    internal static string NfkcCaseFold(string text)
    {
        ArgumentNullException.ThrowIfNull(text);
        if (IsAscii(text)) return AsciiLower(text);
        return Nfkc(CaseFold(Nfkc(text)));
    }

    /// <summary>The general category of a code point; unassigned code points are <see cref="UnicodeCategory.OtherNotAssigned"/>.</summary>
    internal static UnicodeCategory GetCategory(int codePoint)
    {
        if ((uint)codePoint > 0x10FFFF) return UnicodeCategory.OtherNotAssigned;
        return (UnicodeCategory)(CategoryRuns[Run(CategoryRuns, codePoint, 5)] & 0x1F);
    }

    /// <summary>The general category of the character or surrogate pair at an index of a string.</summary>
    internal static UnicodeCategory GetCategory(string text, int index)
    {
        ArgumentNullException.ThrowIfNull(text);
        int i = index;
        return GetCategory(Next(text, ref i));
    }

    /// <summary>The canonical combining class of a code point.</summary>
    internal static int CombiningClass(int codePoint) =>
        codePoint < FirstCombining || codePoint > 0x10FFFF ? 0 : CombiningClassRuns[Run(CombiningClassRuns, codePoint, 8)] & 0xFF;

    private static string Normalize(string text, bool compatibility, bool compose)
    {
        ArgumentNullException.ThrowIfNull(text);
        if (IsAscii(text)) return text;
        var buffer = new List<int>(text.Length + 8);
        for (int i = 0; i < text.Length;)
        {
            Decompose(Next(text, ref i), compatibility, buffer);
        }

        Reorder(buffer);
        if (compose) Compose(buffer);
        var builder = new StringBuilder(buffer.Count);
        foreach (int cp in buffer) Append(builder, cp);
        string result = builder.ToString();
        return result == text ? text : result;
    }

    private static void Decompose(int cp, bool compatibility, List<int> output)
    {
        if (cp is >= SBase and < SBase + SCount)
        {
            int index = cp - SBase;
            output.Add(LBase + index / NCount);
            output.Add(VBase + index % NCount / TCount);
            if (index % TCount != 0) output.Add(TBase + index % TCount);
            return;
        }

        if (cp < 0xA0)
        {
            output.Add(cp);
            return;
        }

        if (compatibility && Find(CompatibilityKeys, cp) is int compat and >= 0)
        {
            for (int v = CompatibilityOffsets[compat]; v < CompatibilityOffsets[compat + 1]; v++) output.Add(CompatibilityValues[v]);
            return;
        }

        if (Find(CanonicalKeys, cp) is int canonical and >= 0)
        {
            for (int v = CanonicalOffsets[canonical]; v < CanonicalOffsets[canonical + 1]; v++) output.Add(CanonicalValues[v]);
            return;
        }

        output.Add(cp);
    }

    // The canonical ordering algorithm: a stable sort of each run of non-starters by combining class.
    private static void Reorder(List<int> buffer)
    {
        for (int i = 1; i < buffer.Count; i++)
        {
            int cc = CombiningClass(buffer[i]);
            if (cc == 0) continue;
            int j = i;
            while (j > 0 && CombiningClass(buffer[j - 1]) > cc)
            {
                (buffer[j - 1], buffer[j]) = (buffer[j], buffer[j - 1]);
                j--;
            }
        }
    }

    // The canonical composition algorithm: each character joins the last starter unless a character between them blocks it.
    private static void Compose(List<int> buffer)
    {
        int starter = -1;
        int lastClass = 0;
        int write = 0;
        for (int read = 0; read < buffer.Count; read++)
        {
            int cp = buffer[read];
            int cc = CombiningClass(cp);
            bool adjacent = starter == write - 1;
            if (starter >= 0 && (adjacent || (lastClass != 0 && lastClass < cc)) && Composite(buffer[starter], cp) is int composite and >= 0)
            {
                buffer[starter] = composite;
                continue;
            }

            if (cc == 0) starter = write;
            lastClass = cc;
            buffer[write++] = cp;
        }

        buffer.RemoveRange(write, buffer.Count - write);
    }

    private static int Composite(int first, int second)
    {
        if (second < FirstCombining) return -1;
        if (first is >= LBase and < LBase + LCount && second is >= VBase and < VBase + VCount)
            return SBase + ((first - LBase) * VCount + (second - VBase)) * TCount;
        if (first is >= SBase and < SBase + SCount && (first - SBase) % TCount == 0 && second is > TBase and < TBase + TCount)
            return first + (second - TBase);
        long key = ((long)first << 21) | (uint)second;
        int index = CompositionKeys.BinarySearch(key);
        return index >= 0 ? CompositionValues[index] : -1;
    }

    private static int Find(ReadOnlySpan<int> keys, int cp) => keys.BinarySearch(cp);

    // The index of the run holding a code point: the last run whose first code point is at most the code point.
    private static int Run(ReadOnlySpan<int> runs, int cp, int shift)
    {
        int low = 0, high = runs.Length - 1;
        while (low < high)
        {
            int middle = (low + high + 1) >> 1;
            if (runs[middle] >> shift <= cp) low = middle;
            else high = middle - 1;
        }

        return low;
    }

    private static int Next(string text, ref int index)
    {
        char c = text[index++];
        if (char.IsHighSurrogate(c) && index < text.Length && char.IsLowSurrogate(text[index])) return char.ConvertToUtf32(c, text[index++]);
        return c;
    }

    private static void Append(StringBuilder builder, int cp)
    {
        if (cp < 0x10000) builder.Append((char)cp);
        else
        {
            builder.Append((char)(0xD800 + ((cp - 0x10000) >> 10)));
            builder.Append((char)(0xDC00 + ((cp - 0x10000) & 0x3FF)));
        }
    }

    private static bool IsAscii(string text) => Ascii.IsValid(text);

    private static string AsciiLower(string text)
    {
        int first = text.AsSpan().IndexOfAnyInRange('A', 'Z');
        if (first < 0) return text;
        return string.Create(text.Length, (text, first), static (span, state) =>
        {
            state.text.AsSpan().CopyTo(span);
            for (int i = state.first; i < span.Length; i++)
            {
                if (span[i] is >= 'A' and <= 'Z') span[i] = (char)(span[i] | 0x20);
            }
        });
    }
}
